// Definition (Creates Symbol Table entry with address)
int application_version = 10;
void start_process(int pid) { /* ... */ }


// Reference (Needs Relocation Table entry)
extern int application_version;
extern void start_process(int pid);


// Linker resolves symbols at link time
void entry_point() {
    int current = application_version; // .data section offset
    start_process(current);           // .text section offset
}

// Global scope symbols require linking/loading
// to map symbolic names to absolute memory addresses.
